import{z as i,x as s,o as e,c as n,q as A,j as r,D as a,d as t,s as B,S as o}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"解码控制收束","description":"","frontmatter":{"title":"解码控制收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dec-map.md","filePath":"llm/dec-map.md","lastUpdated":1791063341000}'),p={name:"llm/dec-map.md"};function d(C,E,m,_,h,F){const l=s("Mermaid");return e(),n("div",null,[E[2]||(E[2]=A('<h1 id="解码控制收束" tabindex="-1">解码控制收束 <a class="header-anchor" href="#解码控制收束" aria-label="Permalink to &quot;解码控制收束&quot;">​</a></h1><div class="epigraph"><p>收束不是把十课再讲一遍，而是回答：明天上线解码控制，先钉什么、后上什么、什么永远不碰。</p><footer>—— 据 Willard &amp; Louf, arXiv:2307.09702、XGrammar, arXiv:2411.15100、Cobbe et al., 2021 与 Snell et al., 2024 按本课程整理</footer></div><p><a href="/llm/dec-cost-quality-curve">上一课</a>把全部旋钮收进成本-质量曲线。至此零件齐了：受控生成的四层地图、结构层的编译与缓存、多约束的组合、服务侧的栈、停止语义、流式事件、后处理管线与 \\(N\\) 的交付形态。本课把它们装配成一张地图与一张决策单。上游是采样与掩码的机制课，下游是成本曲线给的分。<strong>本课程到此收束。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>解码控制的决策散在九课里：协议（finish_reason 全集、流式帧、回填规则）、结构（编译优化、缓存键、组合回退）、栈（次序契约、状态归属）、质量旋钮（BoN 形态、分桶）、验收（曲线、口径）。各课局部最优会互相拆台：协议没钉就上流式 UI，截断回填的 OOD 会记到模型头上；缓存键缺分词器指纹，命中率越高越危险；曲线没画就上 \\(N=16\\)，钱花在饱和区。上线要的是顺序，不是并行的清单。</p><p><span class="marginnote">直觉类比：把上线解码控制想成装修房子。钉协议是打水电地基（看不见但全屋踩在上面）；便宜旋钮是换灯刷墙（花钱少见效快）；结构层与多约束是定制柜体（要先量好尺寸再动工）；上 \\(N\\) 是买高端家电（房子没收拾好就买，体验提升有限）。装修的坑几乎都是顺序错了，不是零件买错了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>决策单</strong>，按「先钉协议、再上便宜旋钮、后建结构层、全程带账」排序：</p><ol><li><strong>钉协议</strong>：finish_reason 全集、流式帧（append / replace_tail / event）、一致性三角的回填规则。看不见的地基，其余各课都踩在上面。</li><li><strong>便宜旋钮先行</strong>：采样参数按桶调好，stop 列表与 eos 集合对齐模板，必要的 bias 上线——成本近零，先把分布拧到该有的形状。</li><li><strong>结构层覆盖工具流量</strong>：schema 收敛后编译，产物按「哈希 × 分词器 × 版本」缓存；确定边直接省步。</li><li><strong>多约束按契约组合</strong>：硬约束求交、空集回退写死优先级、每条约束记生效点。</li><li><strong>高价值流量上 \\(N\\)</strong>：按桶级 \\(p\\) 选并发、瀑布或 leader-follow，打分器 SLO 单独钉。</li><li><strong>曲线验收</strong>：每个旋钮上线前后同口径重测，报边际与版本戳。</li></ol><p>永不碰的四件事：无回退策略的空支撑集；把截断当正常结束回填历史；拿打分器分数当交付质量报警；后处理静默改写进历史的文本。</p>',10)),(e(),r(o,null,{default:a(()=>[B(l,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20M1%5B%22%E9%92%89%E5%8D%8F%E8%AE%AE%EF%BC%9Afinish%20%2F%20%E5%B8%A7%20%2F%20%E5%9B%9E%E5%A1%AB%22%5D%20--%3E%20M2%5B%22%E4%BE%BF%E5%AE%9C%E6%97%8B%E9%92%AE%EF%BC%9A%E9%87%87%E6%A0%B7%20%2F%20stop%20%2F%20bias%22%5D%0A%20%20M2%20--%3E%20M3%5B%22%E7%BB%93%E6%9E%84%E5%B1%82%EF%BC%9A%E7%BC%96%E8%AF%91%20%2B%20%E7%BC%93%E5%AD%98%22%5D%0A%20%20M3%20--%3E%20M4%5B%22%E5%A4%9A%E7%BA%A6%E6%9D%9F%EF%BC%9A%E6%B1%82%E4%BA%A4%20%2B%20%E5%9B%9E%E9%80%80%E5%A5%91%E7%BA%A6%22%5D%0A%20%20M4%20--%3E%20M5%5B%22%E9%AB%98%E4%BB%B7%E5%80%BC%E6%B5%81%E9%87%8F%EF%BC%9ABoN%20%E5%BD%A2%E6%80%81%22%5D%0A%20%20M5%20--%3E%20M6%5B%22%E6%9B%B2%E7%BA%BF%E9%AA%8C%E6%94%B6%EF%BC%9A%E8%BE%B9%E9%99%85%20%2B%20%E7%89%88%E6%9C%AC%E6%88%B3%22%5D%0A%20%20M1%20-.-%3E%20STACK%5B%22%E5%A4%84%E7%90%86%E5%99%A8%E6%A0%88%EF%BC%9A%E6%AC%A1%E5%BA%8F%E4%B8%8E%E7%8A%B6%E6%80%81%22%5D%0A%20%20STACK%20--%3E%20M4%0A%20%20CURVE%5B%22%E6%88%90%E6%9C%AC-%E8%B4%A8%E9%87%8F%E6%9B%B2%E7%BA%BF%22%5D%20--%3E%20M5%0A%20%20CURVE%20--%3E%20M6%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>地图的骨架是三条不变量。<strong>不变量一</strong>：掩码改支撑集、不改权重——控制的一切语义都从这句出发，掩码过紧的质量悬崖、空集回退的必要性、约束不修复幻觉，都是它的推论。<strong>不变量二</strong>：每一步 logits 与每一次终止都有唯一责任人——栈的次序契约、会话状态机的 finish 分支、管线的一致性三角，都是「唯一责任人」在不同层面的化身；责任模糊的地方，就是事故查不出原因的地方。<strong>不变量三</strong>：任何质量声明都带着成本与口径——曲线不变量，它让本课程的旋钮与未来的旋钮（新的引导方法、新的验证器）在同一个坐标系里比较。引擎、分词器、schema 工具都会换代，三条不变量定了，决策单的顺序不动。</p><p><span class="marginnote">一张自检表：如果只做三件事——先把 finish_reason 与流式帧钉进协议，再给工具调用流量上带缓存的文法掩码，然后在主力流量画一条带版本戳的成本-质量曲线。多数服务在第三步之前就拿走了大半收益，后面的每一步都要求先证明前面拿不出来了。</span></p><p>六步决策单不是平行的菜单，每一步都依赖前一步交付的东西；顺序错了，后面一步的验收就没有锚点：</p>',4)),(e(),r(o,null,{default:a(()=>[B(l,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E9%92%89%E5%8D%8F%E8%AE%AE%22%5D%20--%3E%7C%22finish_reason%20%E4%B8%8E%E5%B8%A7%E5%AE%9A%E4%B8%8B%E6%9D%A5%22%7C%20B%5B%22%E4%BE%BF%E5%AE%9C%E6%97%8B%E9%92%AE%22%5D%0A%20%20B%20--%3E%7C%22%E5%88%86%E5%B8%83%E5%BD%A2%E7%8A%B6%E5%8F%AF%E5%A4%8D%E7%8E%B0%22%7C%20C%5B%22%E7%BB%93%E6%9E%84%E5%B1%82%EF%BC%9A%E7%BC%96%E8%AF%91%2B%E7%BC%93%E5%AD%98%22%5D%0A%20%20C%20--%3E%7C%22%E6%8E%A9%E7%A0%81%E8%AF%AD%E4%B9%89%E5%8F%AF%E8%A7%A3%E9%87%8A%22%7C%20D%5B%22%E5%A4%9A%E7%BA%A6%E6%9D%9F%E7%BB%84%E5%90%88%22%5D%0A%20%20D%20--%3E%7C%22%E5%90%88%E6%B3%95%E9%9B%86%E5%A5%91%E7%BA%A6%E7%A8%B3%E5%AE%9A%22%7C%20E%5B%22BoN%20%E5%88%86%E6%A1%B6%E4%B8%8A%20N%22%5D%0A%20%20E%20--%3E%7C%22%E5%80%99%E9%80%89%E8%B4%A8%E9%87%8F%E5%8F%AF%E9%87%8F%22%7C%20F%5B%22%E6%9B%B2%E7%BA%BF%E9%AA%8C%E6%94%B6%22%5D%0A%20%20F%20-.-%3E%7C%22%E5%8F%A3%E5%BE%84%E5%8F%8D%E5%93%BA%22%7C%20A%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<p><span class="marginnote">为什么重要：「掩码改支撑集、不改权重」这条不变量如果做反了——比如为了绕开空集偷偷改采样权重——输出看起来还是合法的，但模型的概率分布被换掉了，之后所有质量回退、A/B 对比与评测数字全部失真，而且很难查出来。控制层的每条红线，本质都是在保护「我们还在同一个模型上说话」这个前提。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>这张地图有时效：约束引擎在加代，验证器与测试时计算的最优配比随模型换代移动，流式协议在标准化。边界之外由相邻课程接棒：批里的成员边界与优先级归服务调度，前缀与 KV 的峰值归 KV 管理，上下文拉长之后的显存与调度是下一课程的题目。解码控制交付的始终是同一件事：把「模型应该说什么」之外的全部要求——结构、词法、属性、交付与账单——从希望变成可以验收的机制，并让每一分质量都能在正确的口径下被数出来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>决策单六步：钉协议 → 便宜旋钮 → 结构层 → 组合契约 → BoN 分桶 → 曲线验收。</li><li>三条不变量：掩码只改支撑集、每步有唯一责任人、质量声明带成本与口径；参数换代，顺序不动。</li><li>永不碰：无回退的空支撑集、截断回填历史、打分器分数当交付质量、后处理静默改历史。</li><li>协议（finish_reason、帧、回填）是本课程各课共踩的地基，永远排第一。</li><li>便宜旋钮先于结构层，结构层先于 \\(N\\)；每一步用曲线证明前面的拿不出来了。</li><li>出处：Willard &amp; Louf, arXiv:2307.09702；Dong et al., XGrammar, arXiv:2411.15100；Cobbe et al., 2021；Snell et al., 2024；按本课程十一课整理。</li></ul>',5))])}const f=i(p,[["render",d]]);export{D as __pageData,f as default};
